import re, unicodedata
import pandas as pd, numpy as np

def _h_norm(s):
    s = str(s).lower().replace('đ', 'd')
    s = unicodedata.normalize('NFD', s).encode('ascii', 'ignore').decode()
    return re.sub('\\s+', ' ', s).strip()

def _h_nfc(s):
    return unicodedata.normalize('NFC', str(s))

def _h_money(s):
    if isinstance(s, (int, float, np.integer, np.floating)) and (not isinstance(s, bool)):
        return float(s)
    s = _h_nfc(s).strip().lower().replace('đ', '').replace('₫', '')
    if not s or s in ('nan', 'none'):
        return np.nan
    s = s.replace(' ', '').replace(',', '')
    s = re.sub('[^0-9.\\-]', '', s)
    if s in ('', '-', '.'):
        return np.nan
    try:
        return float(s)
    except Exception:
        return np.nan

def _h_dates(col):
    return pd.to_datetime(pd.Series(col), dayfirst=True, errors='coerce')
_h__b = None

def _h_tables():
    global _h__b
    if _h__b is None:
        b = data
        ct = b['So_chi_tiet_ban_hang__all'].copy()
        ct['dt'] = _h_dates(ct['Ngày'])
        st = ct['Trạng thái'].astype(str).str.strip()
        ct['st_norm'] = np.select([st.str.contains('hủy|huỷ|không giao', case=False, na=False), st.str.contains('trả', case=False, na=False)], ['cancel', 'return'], default='ok')
        ct['ttien'] = ct['Thành tiền'].map(_h_money)
        ct['qty'] = pd.to_numeric(ct['Số lượng'], errors='coerce')
        ct['slqd'] = pd.to_numeric(ct['Số lượng quy đổi'], errors='coerce')
        ct['name_n'] = ct['Tên hàng hóa'].map(_h_norm)
        ct['cust_n'] = ct['Khách hàng'].map(_h_norm)
        sp = None
        for (k, v) in b.items():
            if 'danh' in _h_nfc(k).lower() and isinstance(v, pd.DataFrame):
                sp = v
                break
        sp = sp.rename(columns={c: _h_nfc(c) for c in sp.columns})
        sp['name_n'] = sp['Tên hàng hóa'].map(_h_norm)
        sp['group_n'] = sp['Nhóm hàng hóa'].map(_h_norm)
        cmap = sp.drop_duplicates('name_n').set_index('name_n')
        ct['unit'] = ct['name_n'].map(cmap['Đơn vị tính'])
        ct['group_n'] = ct['name_n'].map(cmap['group_n'])
        gh = None
        for (k, v) in b.items():
            if 'giao' in _h_nfc(k).lower() and isinstance(v, pd.DataFrame):
                gh = v
                break
        gh = gh.rename(columns={c: _h_nfc(c) for c in gh.columns}).copy()
        gh['dt'] = _h_dates(gh['Ngày giao hàng'])
        _h__b = dict(ct=ct, sp=sp, gh=gh)
    return _h__b

def _h_orders_in(ct, start, end):
    (s, e) = (pd.Timestamp(start), pd.Timestamp(end) + pd.Timedelta(days=1))
    return ct[(ct['st_norm'] == 'ok') & (ct['dt'] >= s) & (ct['dt'] < e)]

def _h_order_rev(ct, start, end):
    sub = _h_orders_in(ct, start, end)
    return sub.groupby('Mã đơn hàng')['ttien'].sum()

def _h_revenue(ct, start, end):
    return float(_h_order_rev(ct, start, end).sum())

